/* Final Whistle: read-only, date-scoped editions sourced from Coffee Time and Nexus. */
(function () {
  'use strict';
  const cast = [['Federica Masolin', 'Conduzione'], ['Paolo Condò', 'Il contesto'], ['Billy Costacurta', 'Analisi difensiva'], ['Alex Del Piero', 'Analisi offensiva']];
  const number = value => value !== null && value !== '' && value !== undefined && Number.isFinite(Number(value)) ? Number(value) : null;
  const parse = (value, fallback) => { try { return typeof value === 'string' ? JSON.parse(value) : value || fallback; } catch { return fallback; } };
  function validRow(row, fixture, date) {
    return row && row.game_world_id === 'GW001' && String(row.sm_fixture_id) === String(fixture.id) && row.match_date === (fixture.match_date || date) &&
      String(row.home_sm_club_id) === String(fixture.home_table.id) && String(row.away_sm_club_id) === String(fixture.away_table.id);
  }
  function buildMatch(fixture, date, results, report) {
    const result = (results?.results || []).find(r => validRow(r, fixture, date) && r.result_status === 'COMPLETED');
    const mr = report?.ok && validRow(report.row, fixture, date) ? report.row : null;
    const complete = r => r && number(r.home_score) !== null && number(r.away_score) !== null && number(r.home_score) >= 0 && number(r.away_score) >= 0;
    const row = complete(mr) ? mr : complete(result) ? result : null;
    const rawStats = mr && row === mr ? parse(mr.team_stats_json, {}) : {};
    const stats = rawStats && typeof rawStats === 'object' && !Array.isArray(rawStats) ? rawStats : {};
    const players = mr && row === mr ? parse(mr.players_json, []) : [];
    return { fixture, row, report: !!(mr && row === mr), stats, players: Array.isArray(players) ? players : [],
      goals: Array.isArray(stats.scorers) ? stats.scorers : [],
      conflict: !!(complete(mr) && complete(result) && (Number(mr.home_score) !== Number(result.home_score) || Number(mr.away_score) !== Number(result.away_score))) };
  }
  const EDITORIAL={"369328897":{"title":"Un minuto per spegnere la rimonta","blocks":[{"speaker":"studio","text":"L’Hertha vola in semifinale, ma dentro questo 4–1 c’è un minuto che merita di essere raccontato. Al 56′ Alajbegović riapre la partita; al 57′ Tchouaméni restituisce ai berlinesi il doppio vantaggio. Il Parma intravede la rimonta e si ritrova immediatamente a inseguire. Questa mattina, a Coffee Time, parlavamo della pazienza necessaria per affrontare un Parma passato due volte ai rigori dopo altrettanti 0–0. L’Hertha ha trovato presto il vantaggio e poi ha colpito anche sui calci piazzati. Giorgia, partiamo da te e da Tommy Mello."},{"speaker":"home_reporter","text":"Federica, il gol di Højbjerg al nono minuto ha cambiato subito il problema che l’Hertha doveva risolvere: niente lunga attesa davanti a una partita bloccata. E il centrocampo ha fatto molto più che accompagnare l’attacco: hanno segnato Højbjerg, Zieliński e Tchouaméni. Il 62% di possesso e i 22 tiri descrivono la pressione dei berlinesi, ma il Parma nella ripresa è riuscito a trovare spazio. È proprio da lì che voglio cominciare con il mister."},{"speaker":"home_question","text":"Tommy, questa mattina avevi chiesto precisione e pazienza. Sul 2–1, invece, serviva una risposta immediata: quanto pesa quel gol di Tchouaméni un minuto dopo quello del Parma?"},{"speaker":"home_manager","text":"Pesa tantissimo, perché avevamo appena rimesso in discussione una partita che sembrava sotto controllo. Mi è piaciuto che la squadra abbia continuato a giocare, senza farsi prendere dalla paura. Però dobbiamo guardare anche quello che viene prima: all’inizio della ripresa il Parma ci aveva già impegnato con Kramarić. Quel segnale dovevamo leggerlo meglio."},{"speaker":"home_question","text":"Quattro gol, nessuno dei quali firmato da un attaccante. Lewandowski, però, serve il pallone del 3–1. È questa la partecipazione che cerchi nel tuo 4-3-3?"},{"speaker":"home_manager","text":"Sì. Robert deve aiutarci a segnare anche quando non conclude lui. Sul terzo gol mette Tchouaméni nelle condizioni di fare male e per me quel contributo conta. Se diventiamo una squadra che aspetta soltanto il gol del centravanti, siamo più facili da leggere. Stasera abbiamo trovato soluzioni diverse."},{"speaker":"home_question","text":"Zieliński segna su punizione e poi batte il corner del gol di Saliba. Quanto hanno pesato i piazzati contro una squadra arrivata qui grazie alla solidità difensiva?"},{"speaker":"home_manager","text":"Molto. Il suo gol ci permette di andare all’intervallo sul 2–0; il corner del quarto ci dà un margine più ampio. In una partita di coppa queste occasioni possono decidere quanto devi soffrire. Piotr ha messo qualità in entrambi gli episodi."},{"speaker":"home_question","text":"Ora il Celtic, ancora all’Olympiastadion. L’obiettivo è alzare la coppa?"},{"speaker":"home_manager","text":"Sì, vogliamo alzarla. Ma per arrivare alla finale dobbiamo superare il Celtic e servirà un’altra prestazione importante. Giocare qui ci dà una spinta enorme: vogliamo regalarci un’altra serata così, correggendo anche quello che oggi non abbiamo fatto bene."},{"speaker":"studio","text":"Mello si prende la qualificazione, ma riconosce i segnali concessi nella ripresa. Passiamo al Parma: Marco Nosotti è con Lauro Crasti."},{"speaker":"away_reporter","text":"Il Parma aveva costruito le precedenti qualificazioni sulla capacità di restare dentro partite molto chiuse. Stasera il gol subito dopo nove minuti ha tolto subito quella possibilità. Nella ripresa, però, una reazione c’è stata: prima la conclusione di Kramarić, poi il gol di Alajbegović. Il rimpianto è non aver dato durata a quel momento favorevole. Il 3–1 arriva prima ancora che il Parma possa provare a mettere pressione sul risultato."},{"speaker":"away_question","text":"Lauro, dopo il gol di Alajbegović la partita sembra riaperta. Un minuto dopo arriva Tchouaméni: è lì che vi sfugge l’occasione di cambiare la serata?"},{"speaker":"away_manager","text":"Sì, quello è il rimpianto più grande. Avevamo trovato il gol e potevamo costringerli a gestire una situazione diversa. Invece abbiamo concesso subito un’altra conclusione decisiva. Quando riesci a rientrare contro una squadra così, devi darle la sensazione che la partita sia davvero cambiata. Noi non ci siamo riusciti."},{"speaker":"away_question","text":"Avevi scelto il 4-2-3-1, con il pressing nella vostra metà campo. L’Hertha ha comunque prodotto 22 tiri: siete rimasti troppo bassi o non siete riusciti a uscire dopo aver recuperato palla?"},{"speaker":"away_manager","text":"Non siamo riusciti a dare abbastanza continuità alle uscite. Cercavamo equilibrio, ma se il pallone torna troppo spesso agli avversari finisci per difendere sempre. E loro avevano giocatori capaci di arrivare alla conclusione da zone diverse. La ripresa ci ha fatto vedere che potevamo creare qualcosa, ma non l’abbiamo fatto con sufficiente regolarità."},{"speaker":"away_question","text":"Due dei quattro gol arrivano da palla inattiva. Quanto pesa questo dato nel giudizio sulla vostra prestazione difensiva?"},{"speaker":"away_manager","text":"Pesa. La punizione di Zieliński è un gesto di qualità, ma dobbiamo analizzare anche il fallo che porta a quell’occasione. Sul corner del quarto gol dobbiamo rivedere come abbiamo difeso l’area. Non possiamo spiegare tutto con la bravura dell’Hertha: ci sono responsabilità nostre da affrontare."},{"speaker":"away_question","text":"Cosa salvi di questa eliminazione?"},{"speaker":"away_manager","text":"La volontà di reagire dopo il 2–0. Non basta per essere soddisfatti, ma è il punto da cui ripartire. Alajbegović ci ha rimesso in partita; dovevamo sostenerlo con una gestione migliore dei minuti successivi. Complimenti all’Hertha, che ha meritato la qualificazione."},{"speaker":"studio","text":"Due letture che si incontrano sullo stesso episodio. Paolo, quanto racconta questa partita quel minuto tra il 2–1 e il 3–1?"},{"speaker":"context","text":"Racconta la possibilità che il Parma aveva appena riaperto e la rapidità con cui l’Hertha gliel’ha tolta. Il 4–1 finale rischia di farci dimenticare che al 56′ c’era un solo gol di distanza. Il merito dei berlinesi è aver trovato subito una risposta; per il Parma resta il rimpianto di non aver potuto costruire una fase di pressione su quel risultato."},{"speaker":"defence","text":"Io riprenderei l’osservazione di Mello. Prima del gol di Alajbegović c’era stata l’occasione di Kramarić al 46′: quindi la ripresa aveva già dato un avvertimento all’Hertha. La vittoria non deve cancellarlo. Dall’altra parte, Crasti ha ragione a interrogarsi sulla continuità delle uscite. Difendere nella propria metà campo richiede anche la capacità di risalire: altrimenti aumentano le situazioni da gestire davanti alla porta. Otto tiri del Parma contro ventidue dell’Hertha aiutano a capire quanto sia stato diverso il peso offensivo delle due squadre."},{"speaker":"attack","text":"E quei quattro gol dell’Hertha mostrano modi diversi di arrivare alla conclusione. Højbjerg scambia con Tchouaméni; sul 3–1 è Lewandowski a servire Tchouaméni. Il centravanti non segna, ma partecipa all’azione che spegne la rimonta. Poi c’è Zieliński: la punizione del 2–0 e il corner per Saliba. Tchouaméni è il migliore in campo del report, con un gol, un assist e voto nove; anche Zieliński prende nove. Sono due prestazioni decisive, per ragioni diverse."},{"speaker":"studio","text":"L’Hertha passa con quattro marcatori diversi e una risposta immediata nel momento più delicato. Il Parma saluta la coppa con il rimpianto di una rimonta durata appena un minuto. Per Mello ora c’è il Celtic: l’Olympiastadion aspetta un’altra notte di coppa."}],"penalties":null,"signature":"204ac0afb882622cf32cc8f11552a44734c6e73e6b7571d60e1b99d020bc8deb"},"369328898":{"title":"Il Celtic ritrova la coppa, il Palermo perde il suo minuto","blocks":[{"speaker":"studio","text":"Il Celtic vince 3–1 a Palermo e raggiunge l’Hertha in semifinale. Ma la notizia non è soltanto il risultato: dopo il pesante stop in campionato, Sir Simone ritrova una squadra capace di prendersi il vantaggio e di reagire appena gli avversari tornano in partita. Jackson apre, Brown raddoppia su punizione. Quando Rigg accorcia al 61′, Saibari risponde al 62′. Per il Palermo, che arrivava dalla prima vittoria in campionato, il momento della possibile rimonta dura un minuto. Bruno, come si legge questa eliminazione da bordo campo?"},{"speaker":"home_reporter","text":"Federica, il Palermo non è rimasto senza iniziativa: ha guadagnato otto corner e trovato il gol con l’intesa fra Pulisic e Rigg. Ma non ha dato continuità a queste situazioni. Il Celtic ha avuto più possesso, più conclusioni e soprattutto ha segnato nei passaggi che hanno pesato maggiormente: il vantaggio al 14′, il raddoppio poco prima dell’intervallo e il 3–1 immediatamente dopo la rete rosanero. Con Al Zubeidi voglio partire proprio da quel momento."},{"speaker":"home_question","text":"Mister, Rigg segna al 61′ e Saibari risponde un minuto dopo. Avevate appena riaperto la partita: cosa vi è mancato per far durare quella spinta?"},{"speaker":"home_manager","text":"Ci è mancata l’attenzione nell’azione successiva. Il nostro gol doveva darci fiducia, ma anche ricordarci che c’era ancora una partita da gestire. Abbiamo permesso al Celtic di tornare subito a due gol di vantaggio e così abbiamo sprecato la possibilità di mettergli davvero pressione. È il passaggio che mi lascia più amarezza."},{"speaker":"home_question","text":"Avevi scelto un atteggiamento offensivo, pressing alto e difesa alta. Il Celtic ha chiuso con il 57% di possesso: non siete riusciti a recuperare il pallone dove volevate?"},{"speaker":"home_manager","text":"Volevamo essere attivi, non aspettare soltanto. Ma l’intenzione deve diventare un lavoro fatto bene da tutti. Quando loro riuscivano a giocare, noi facevamo fatica a riprendere il controllo. Non basta chiedere di andare a pressare: dobbiamo capire come accompagnare quella pressione e come restare compatti se non recuperiamo subito il pallone."},{"speaker":"home_question","text":"Al 60′ entrano Barrios e Jauregizar, al 61′ arriva il vostro gol. Possiamo parlare di una risposta dai cambi o sarebbe una lettura troppo semplice?"},{"speaker":"home_manager","text":"Volevo energie nuove, ma non attribuirei automaticamente il gol alle sostituzioni. Nell’azione sono Pulisic e Rigg a trovare la giocata giusta. Quello che mi interessa è che la squadra aveva ancora la possibilità di reagire. Il problema è che non abbiamo protetto quella reazione abbastanza a lungo."},{"speaker":"home_question","text":"Dopo i quattro gol a Genova, questa sconfitta ridimensiona la fiducia ritrovata?"},{"speaker":"home_manager","text":"Ci ricorda che una vittoria non cancella tutto quello che dobbiamo migliorare. La fiducia serve per lavorare, non per sentirsi arrivati. Oggi usciamo dalla coppa contro una squadra che ha sfruttato meglio le proprie occasioni. Dobbiamo accettarlo e correggere ciò che ci ha impedito di restare dentro la partita."},{"speaker":"studio","text":"Dall’altra parte, il Celtic ha ritrovato una risposta proprio dove Coffee Time aveva posto la domanda: quale squadra avremmo visto dopo la sconfitta in campionato? Nicola Roggero è con Sir Simone."},{"speaker":"away_reporter","text":"Il Celtic ha risposto con tre protagonisti diversi. Jackson conclude di prima sul passaggio di Schjelderup, Brown segna su punizione e poi partecipa allo scambio che porta al gol di Saibari. C’è anche un episodio da leggere correttamente: al 43′ Jackson trova ancora la rete, ma viene fermato per fuorigioco. Il vantaggio all’intervallo resta quindi di due gol. La squadra non ha avuto bisogno di quel terzo gol per arrivare alla pausa avanti; nella ripresa, però, ha dovuto reagire a quello del Palermo."},{"speaker":"away_question","text":"Sir Simone, stamattina volevi ritrovare qualità e attenzione insieme. Ti soddisfa di più il primo tempo o la risposta immediata al gol di Rigg?"},{"speaker":"away_manager","text":"La risposta al loro gol, perché lì potevamo complicarci la serata. Il primo tempo ci aveva dato un vantaggio importante, ma sul 2–1 non potevamo vivere di quello che avevamo fatto prima. Abbiamo continuato a cercare una giocata e l’abbiamo trovata subito. È una reazione che mi piace, anche se avrei preferito non concedere la rete che l’ha resa necessaria."},{"speaker":"away_question","text":"Jackson è il migliore in campo, Brown chiude con un gol e un assist. Quanto è importante avere più riferimenti capaci di decidere una partita?"},{"speaker":"away_manager","text":"Molto, perché ci permette di non aspettare sempre la stessa soluzione. Jackson ci ha dato il primo vantaggio, Brown ha segnato un gol importante prima dell’intervallo e poi ha partecipato al terzo. Saibari ha concluso quell’azione nel momento giusto. Voglio che ognuno si senta responsabile di ciò che possiamo costruire."},{"speaker":"away_question","text":"Sul 2–0 arriva anche il gol annullato a Jackson. Come si mantiene la lucidità quando sembra di aver già chiuso la partita e invece il margine resta più piccolo?"},{"speaker":"away_manager","text":"Ricordandosi il risultato reale. Quel gol non vale e la partita resta sul 2–0. Non dobbiamo comportarci come se avessimo un vantaggio che non c’è. Nella ripresa il Palermo ci ha dimostrato quanto basti poco per rimettere tutto in discussione."},{"speaker":"away_question","text":"Adesso l’Hertha all’Olympiastadion. Che cosa porti con te da questa vittoria?"},{"speaker":"away_manager","text":"La capacità di reagire e la partecipazione di più giocatori alle azioni decisive. Ma la semifinale richiederà un’altra prestazione. L’Hertha ha appena segnato quattro gol: sappiamo che dovremo essere precisi con il pallone e molto attenti quando lo avranno loro."},{"speaker":"studio","text":"Paolo, il Celtic ritrova continuità in coppa, mentre il Palermo non riesce a trasformare la fiducia del campionato in una qualificazione."},{"speaker":"context","text":"È il motivo per cui questa mattina tenevamo distinti i due percorsi. Il Celtic aveva già mostrato di saper essere incisivo in coppa; la sconfitta in campionato non aveva cancellato quelle qualità. Il Palermo arrivava con un risultato positivo alle spalle, ma oggi ha dovuto affrontare una partita nuova. Il suo rimpianto sta soprattutto nel non aver costruito nulla sul 2–1."},{"speaker":"defence","text":"Entrambe avevano scelto difesa alta e pressione in tutto il campo, ma questo non significa che abbiano difeso nello stesso modo o con la stessa efficacia. Il Celtic ha concesso il gol a Rigg e deve rivedere quell’azione. Il Palermo, invece, deve partire dalla risposta di Saibari: dopo aver segnato, non puoi considerare il lavoro finito. Devi subito ritrovare posizioni e attenzione."},{"speaker":"attack","text":"Jackson merita il riconoscimento del report: sul primo gol attacca la conclusione di prima sul servizio di Schjelderup. Ma Brown incide in due modi diversi, con la punizione e con lo scambio che libera Saibari. Per il Palermo, il passaggio di Pulisic a Rigg è una giocata da conservare: dimostra che la soluzione c’era. È mancata la capacità di ripeterla e di darle un seguito."},{"speaker":"studio","text":"Il Celtic passa e prepara la trasferta di Berlino. Il Palermo si ferma ai quarti: il gol di Rigg aveva aperto una possibilità, Saibari l’ha richiusa nell’azione successiva."}],"penalties":null,"signature":"6b1a2b4d074fae1440abb62b848b2f6f223ca50d8097f14863e428259948fe35"},"369328899":{"title":"Atta decide dal dischetto, la Roma si ferma all’ultimo rigore","blocks":[{"speaker":"studio","text":"Kaiserslautern e Roma non si separano nei novanta minuti: Uzun segna al 5′, Veiga risponde al 27′. La qualificazione si decide ai rigori, cinque a quattro per i tedeschi. Dopo otto trasformazioni consecutive, Ruiz calcia fuori e Atta segna il tiro decisivo. Ma sarebbe ingiusto raccontare questa partita cominciando soltanto dal dischetto: ci sono il vantaggio rapido della Roma, la risposta del Kaiserslautern e una parata di Martínez su Atta all’86′ che tiene tutto aperto. Giorgia Rossi, partiamo dai qualificati."},{"speaker":"home_reporter","text":"Il Kaiserslautern ha dovuto inseguire quasi subito. Non ha replicato il punteggio largo ottenuto contro il Celtic in campionato, e proprio questa mattina Vardan ci aveva invitato a non confondere una partita con l’altra. Ha trovato il pareggio con Veiga, servito da Isak, e nella ripresa ha cercato il vantaggio anche con i giocatori entrati dalla panchina. Atta ha avuto una grande occasione all’86′; Martínez ha mandato il pallone sul palo prima di recuperarlo. Dal dischetto, invece, il capitano non ha lasciato scampo."},{"speaker":"home_question","text":"Vardan, gol subito dopo cinque minuti e partita subito da rincorrere. Che cosa ti è piaciuto della risposta fino al pareggio di Veiga?"},{"speaker":"home_manager","text":"Non ci siamo messi a cercare il gol con fretta e disordine. Dovevamo rientrare, ma senza regalare alla Roma la possibilità di allungare. L’azione fra Isak e Veiga ci ha riportato in equilibrio. Era importante arrivare al pareggio continuando a giocare, non affidandoci soltanto a un episodio casuale."},{"speaker":"home_question","text":"Al 60′ hai cambiato quattro uomini, fra cui Isak e Veiga, protagonisti dell’1–1. Come leggi quella scelta dopo una qualificazione arrivata ai rigori?"},{"speaker":"home_manager","text":"La leggo per quello che cercavo in quel momento: altre energie e altre soluzioni per provare a vincere. Isak e Veiga avevano dato un contributo importante, ma la partita richiedeva ancora lavoro. Chi è entrato ci ha aiutato a continuare a cercare la porta; poi Ebnoutalib, Estêvão e Karl sono stati precisi anche dal dischetto."},{"speaker":"home_question","text":"Martínez nega il gol ad Atta all’86′, poi Atta si ritrova davanti allo stesso portiere con il rigore che può decidere tutto. Che valore dai a quella trasformazione?"},{"speaker":"home_manager","text":"Il valore di una responsabilità presa fino in fondo. Aveva avuto un’occasione importante e non era entrata; sul rigore doveva concentrarsi su un’altra conclusione, senza portarsi dietro quella precedente. Ha segnato e ci ha dato la semifinale. Ma siamo arrivati al quinto tiro grazie alla precisione di tutti quelli che avevano calciato prima."},{"speaker":"home_question","text":"Isak è il migliore in campo del report pur essendo uscito al 60′. È la conferma che il lavoro del centravanti non si misura soltanto nei gol?"},{"speaker":"home_manager","text":"Assolutamente. Serve Veiga per il pareggio e ci aiuta a costruire situazioni offensive. Voglio che i miei attaccanti incidano nel gioco, non che aspettino soltanto il pallone da spingere dentro. Il suo contributo è stato importante per riportare la partita dove volevamo."},{"speaker":"studio","text":"La Roma esce dopo essere andata in vantaggio e dopo aver tenuto aperto il confronto fino all’ultimo tiro. Paolo Assogna è con Pep Buitre."},{"speaker":"away_reporter","text":"Per la Roma ci sono due rimpianti distinti: non aver dato seguito al vantaggio di Uzun e non aver trovato il secondo gol prima dei rigori. Martínez ha tenuto in corsa i giallorossi anche nel finale, prima su Ebnoutalib e poi su Atta. La serie dal dischetto è stata precisissima fino al tiro di Ruiz: Šeško, Tadić, Thauvin e Uzun avevano tutti segnato. È un’eliminazione che non può essere ridotta a un solo errore."},{"speaker":"away_question","text":"Pep, eravate avanti dopo cinque minuti con Uzun su passaggio di Tadić. Il rimpianto maggiore è non aver sfruttato quel vantaggio o non aver trovato un’altra rete dopo il pareggio?"},{"speaker":"away_manager","text":"Sono due momenti della stessa partita. Il gol iniziale ci aveva dato una buona opportunità, ma non potevamo pensare di gestire tutto il tempo che restava. Dopo il loro pareggio avevamo ancora spazio per cercare il secondo. Non siamo riusciti a farlo e poi, nel finale, Martínez ci ha aiutato a restare in corsa."},{"speaker":"away_question","text":"Hai cambiato cinque giocatori al 60′. Tre subentrati, Šeško, Thauvin e Ruiz, sono poi andati dal dischetto. L’esito dei rigori cambia il giudizio su quelle sostituzioni?"},{"speaker":"away_manager","text":"No, i cambi andavano valutati dentro la partita. Volevo provare a darle un nuovo impulso. Non possiamo dire che una sostituzione sia giusta perché un giocatore segna il rigore e un’altra sbagliata perché lo manca. Chi entra si assume una responsabilità, esattamente come chi ha cominciato."},{"speaker":"away_question","text":"Cosa dici a Ruiz dopo il quinto rigore fuori?"},{"speaker":"away_manager","text":"Che questa eliminazione appartiene a tutti. Ha avuto il coraggio di calciare, come gli altri. Non voglio che si porti addosso una responsabilità che cancella novanta minuti di calcio. Dobbiamo guardare anche alle occasioni che non abbiamo trasformato e a quelle che abbiamo concesso."},{"speaker":"away_question","text":"Martínez vi tiene vivi fino ai rigori. Da cosa riparti dopo una serata così?"},{"speaker":"away_manager","text":"Dalla capacità di restare in partita, ma anche dalla consapevolezza che possiamo fare meglio prima dell’ultima conclusione. Il nostro portiere ci ha dato una possibilità importante. Dovevamo provare a sfruttarla con più continuità davanti. Complimenti al Kaiserslautern: ha calciato cinque rigori senza sbagliare."},{"speaker":"studio","text":"Paolo Condò, una qualificazione decisa dal quinto tiro dopo una partita in cui entrambe avevano trovato un modo per fare male."},{"speaker":"context","text":"La sequenza dei rigori è chiarissima: le prime quattro coppie segnano, poi arrivano l’errore di Ruiz e la trasformazione di Atta. Ma la storia della serata comprende anche la risposta al vantaggio della Roma e le occasioni della ripresa. Il Kaiserslautern supera un altro turno dal dischetto; la Roma esce senza che questo autorizzi a trasformare l’ultimo tiratore nell’unico responsabile."},{"speaker":"defence","text":"Mi soffermerei su Martínez. Al 71′ interviene su Ebnoutalib e all’86′ devia la conclusione di Atta sul palo, poi recupera il pallone. Sono due episodi che permettono alla Roma di arrivare ai rigori. Il Kaiserslautern, dall’altra parte, reagisce al gol preso quasi subito senza concedere un secondo vantaggio. La gestione dell’emergenza iniziale è una parte importante della sua qualificazione."},{"speaker":"attack","text":"Il pareggio nasce dall’intesa Isak–Veiga: chi serve il pallone conta quanto chi conclude. Isak prende nove ed è il migliore in campo del report, anche senza segnare. Poi c’è Atta, che all’86′ trova un grande intervento del portiere e ai rigori torna a calciare contro lo stesso avversario. Sono situazioni diverse, ma entrambe chiedono di assumersi la responsabilità dell’ultima giocata."},{"speaker":"studio","text":"Il Kaiserslautern è in semifinale: 1–1 nei tempi regolamentari, 5–4 ai rigori. Alla Roma resta una serata combattuta e il rimpianto di non averla risolta prima del dischetto. Per Vardan, la coppa continua."}],"penalties":[5,4],"signature":"2d2977e622e676cd3adf5280e1536e4ed618aef72c9e98a2e0265ce3421494ad"},"369328900":{"title":"Schick firma la semifinale, il Legia si ferma davanti alla porta","blocks":[{"speaker":"studio","text":"Tre gol, voto dieci e il premio di migliore in campo: Patrik Schick si prende Tottenham–Legia e manda gli Spurs in semifinale. Segna al 36′, al 58′ e all’88′. Ma dietro la tripletta ci sono due passaggi decisivi di Zaccagni, il contributo di Højlund dalla panchina e una partita che il Legia aveva avuto la possibilità di indirizzare prima del vantaggio inglese. Massimo Marianella, cominciamo dal protagonista e dal lavoro che gli ha permesso di incidere."},{"speaker":"home_reporter","text":"Federica, Schick conclude tutte e tre le azioni dei gol, ma non arriva da solo davanti alla porta. Zaccagni lo serve sia sull’1–0 sia sul 2–0; nel finale è Højlund a dargli il pallone della tripletta. Il Tottenham chiude con quindici tiri contro undici, quindi non parliamo di un avversario che non abbia mai provato ad attaccare. La differenza è stata soprattutto nella capacità di rendere decisive le occasioni. Prima del vantaggio, Grifo aveva colpito l’esterno del palo per il Legia."},{"speaker":"home_question","text":"Max, Schick segna tre volte e prende dieci. Quanto della sua serata nasce dal modo in cui siete riusciti a servirlo?"},{"speaker":"home_manager","text":"Molto. Lui è stato bravissimo a concludere, ma dobbiamo riconoscere il lavoro di chi lo ha messo nelle condizioni di farlo. Zaccagni trova due palloni importanti, Højlund entra e partecipa al terzo gol. È quello che chiedo: chi arriva alla conclusione deve sentire il sostegno della squadra, non dover inventare tutto da solo."},{"speaker":"home_question","text":"Il Legia colpisce l’esterno del palo con Grifo al 19′. Quanto sarebbe sbagliato leggere il 3–0 come una partita senza difficoltà?"},{"speaker":"home_manager","text":"Sarebbe sbagliato. Sullo 0–0 loro hanno avuto quell’occasione e nella ripresa Chevalier ha dovuto intervenire su Berchiche. Il risultato ci premia, ma non cancella ciò che abbiamo concesso. Mi interessa che i ragazzi riconoscano questi momenti, perché in un’altra partita possono pesare diversamente."},{"speaker":"home_question","text":"Al 60′ cambi cinque giocatori, due minuti dopo il raddoppio. Era importante dare energia senza perdere il controllo della gara?"},{"speaker":"home_manager","text":"Sì, c’era ancora mezz’ora da giocare e non volevo che considerassimo il lavoro finito. Chi è entrato doveva tenere alto il livello dell’attenzione e continuare a offrirci soluzioni. Il pallone di Højlund per Schick nel finale è un contributo concreto, ma tutti i subentrati avevano il compito di accompagnare la squadra fino alla fine."},{"speaker":"home_question","text":"A Coffee Time avevamo ricordato i sette punti di distanza dal Legia in campionato. Questa vittoria cambia il modo in cui guardate al vostro valore?"},{"speaker":"home_manager","text":"Ci dà fiducia, ma quei punti restano nella classifica del campionato. Oggi abbiamo meritato di passare questa partita di coppa. Per crescere dobbiamo ripetere le prestazioni, non usare una vittoria per cancellare quello che abbiamo lasciato per strada prima. Intanto ci godiamo una semifinale conquistata sul campo."},{"speaker":"studio","text":"Il Legia lascia la coppa con un punteggio netto, ma con episodi da analizzare prima di fermarsi al risultato. Valentina Caruso è con Luciano Catalano."},{"speaker":"away_reporter","text":"Il Legia non è stato lontano dal Tottenham nel possesso: 49% contro 51%. Ha anche prodotto undici tiri, ma soltanto due nello specchio. L’esterno del palo di Grifo al 19′ e la conclusione di Berchiche respinta da Chevalier al 55′ sono i due passaggi su cui soffermarsi: prima del vantaggio e prima del raddoppio degli Spurs, c’era ancora la possibilità di cambiare la partita. Poi Schick ha fatto pesare ogni apertura che gli è stata concessa."},{"speaker":"away_question","text":"Luciano, Grifo sfiora il vantaggio e Berchiche cerca il pareggio poco prima del 2–0. Il rimpianto è nelle occasioni mancate o nella gestione delle azioni successive?"},{"speaker":"away_manager","text":"In entrambe le cose. Quelle occasioni potevano aiutarci, ma non possiamo fermarci a pensare a come sarebbe andata se fossero entrate. Dovevamo continuare a difendere bene e a costruire altre situazioni. Il Tottenham ha trovato tre gol e noi nessuno: dobbiamo analizzare anche perché non siamo riusciti a dare seguito alle nostre possibilità."},{"speaker":"away_question","text":"Zaccagni serve Schick sia per il primo sia per il secondo gol. Non siete riusciti a interrompere quella connessione?"},{"speaker":"away_manager","text":"È una delle cose che dobbiamo rivedere. Quando una combinazione ti fa male una volta, devi riconoscerla e provare a limitarla meglio. Non basta occuparsi soltanto di chi conclude: bisogna lavorare anche sul pallone che gli arriva. Stasera non siamo stati abbastanza efficaci in questo."},{"speaker":"away_question","text":"Sul primo gol il report segnala un errore di Courtois. Quanto incide un episodio del genere sul giudizio della partita?"},{"speaker":"away_manager","text":"Incide sul risultato di quel momento, ma non voglio usarlo per spiegare tutto. Courtois ha fatto anche una parata su Schick prima del raddoppio. Ci sono responsabilità collettive nelle occasioni che concediamo, e ci sono le nostre occasioni non sfruttate. Una sconfitta per tre a zero non si analizza scegliendo una sola persona."},{"speaker":"away_question","text":"Avevi scelto un 4-3-3 offensivo, ma avete chiuso con due tiri nello specchio. Dove cercare il miglioramento?"},{"speaker":"away_manager","text":"Nella qualità dell’ultima parte dell’azione. Volevamo essere pericolosi e qualche situazione l’abbiamo creata, ma troppo poco è arrivato davvero a impegnare il portiere. Dobbiamo scegliere meglio quando concludere e come accompagnare chi ha il pallone. Il Tottenham è stato più concreto e ha meritato la qualificazione."},{"speaker":"studio","text":"Paolo, questa mattina avevamo detto che la classifica non avrebbe assegnato la semifinale. Il campo ha dato una risposta molto precisa."},{"speaker":"context","text":"Ha premiato il Tottenham, che ha trasformato una partita ancora aperta nei suoi momenti decisivi. Il vantaggio in campionato del Legia era un elemento di contesto, non una garanzia. Gli Spurs possono prendere fiducia da questa vittoria; il Legia deve tenere insieme l’eliminazione e il percorso che aveva costruito, senza usare l’uno per cancellare l’altro."},{"speaker":"defence","text":"Il primo episodio da non dimenticare è il palo esterno di Grifo sullo 0–0. Il secondo è l’intervento di Chevalier al 55′, quando bastava un gol per pareggiare. Il Tottenham ha tenuto la porta inviolata, ma ha avuto bisogno anche del proprio portiere. Sul Legia condivido l’analisi di Catalano: Zaccagni e Schick si trovano due volte per segnare, quindi bisogna rivedere sia la pressione sul passaggio sia la difesa del destinatario."},{"speaker":"attack","text":"Schick è il volto della serata: tre gol e voto dieci. Ma i due assist di Zaccagni spiegano perché la sua partita sia anche il risultato di un’intesa. Sul primo gol c’è l’errore del portiere, sul secondo c’è ancora il servizio di Zaccagni, sul terzo arriva il pallone di Højlund. Il Tottenham riesce a continuare ad alimentare il proprio attaccante anche dopo i cambi: è un segnale importante."},{"speaker":"studio","text":"Il Tottenham passa con la tripletta del suo capitano. Il Legia si ferma ai quarti, fra occasioni non sfruttate e difficoltà nel contenere l’intesa Zaccagni–Schick. Per Max Zanoni la coppa continua, con una serata da ricordare e una semifinale da preparare."}],"penalties":null,"signature":"d0ac7935e295199a7b0bc8b1bbe08cf7dedc647a34cc960d3854b6e1a1ac8be7"}};
  function reportEvidence(row) {
    return JSON.stringify(['game_world_id','sm_fixture_id','match_date','home_sm_club_id','away_sm_club_id','home_score','away_score','penalty_home_score','penalty_away_score','team_stats_json','players_json','events_json','tactics_json'].map(k=>row[k]??null));
  }
  async function attachEditorial(m) {
    if(!m.report)return m;
    const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(reportEvidence(m.row)));
    m.reportSignature=Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
    return m;
  }
  function approvedStory(m) {
    const s=EDITORIAL[String(m.fixture.id)];
    return m.report && s?.signature===m.reportSignature ? s : null;
  }
  function voiced(m,b) {
    const f=m.fixture, studio={studio:0,context:1,defence:2,attack:3};
    if(b.speaker in studio){const person=cast[studio[b.speaker]];return {name:person[0],role:person[1],text:b.text,kind:b.speaker};}
    const side=b.speaker.startsWith('home_')?'home':'away';
    if(b.speaker.endsWith('_manager'))return {name:f[side+'_manager']||'Allenatore '+f[side],role:f[side]+' · La risposta',text:b.text,kind:'answer'};
    const rep=(f.reporters||[]).find(r=>r.side===side);
    return {name:rep?.name||'Inviato '+f[side],role:f[side]+(b.speaker.endsWith('_question')?' · La domanda':' · Bordo campo'),text:b.text,kind:b.speaker.endsWith('_question')?'question':'reporter'};
  }
  // Same editorial structure for new reports: both touchlines, both managers,
  // then distinct studio analysis. Only normalized scorers count as goals;
  // the raw event_type can incorrectly label saves, offsides or shootouts.
  function automaticStory(m) {
    const f=m.fixture,r=m.row,h=Number(r.home_score),a=Number(r.away_score);
    const goals=[...m.goals].sort((x,y)=>Number(x.minute)-Number(y.minute));
    const tactics=parse(r.tactics_json,[]), events=parse(r.events_json,[]);
    const first=goals[0],last=goals.at(-1),mvp=m.players.find(p=>Number(p.man_of_match)===1);
    const ph=number(r.penalty_home_score),pa=number(r.penalty_away_score);
    const penaltyText=ph!==null&&pa!==null?` Ai rigori ${ph}–${pa}.`:'';
    const opening=first?`La prima svolta è il gol di ${first.player_name} al ${first.minute}′.`:'Nessun gol separa le due squadre: la lettura della partita passa dalle occasioni e dalla tenuta difensiva.';
    const blocks=[{speaker:'studio',text:`${f.home}–${f.away} finisce ${h}–${a}.${penaltyText} ${opening} Andiamo dai due inviati per capire le scelte degli allenatori e i passaggi che hanno pesato sul risultato.`}];
    for(const side of ['home','away']) {
      const other=side==='home'?'away':'home',gf=side==='home'?h:a,ga=side==='home'?a:h;
      const own=goals.filter(g=>g.team_side===side),conceded=goals.filter(g=>g.team_side===other),s=m.stats[side]||{},against=m.stats[other]||{};
      const t=Array.isArray(tactics)?tactics.find(t=>t.team_side===side&&Number(t.snapshot_minute)===0):null;
      const landmark=conceded[0]||own[0];
      let reading=gf>ga?'Il risultato premia la squadra, ma va letto distinguendo ciò che ha costruito da ciò che ha concesso.':gf<ga?'La sconfitta va analizzata nelle due aree: nelle occasioni non sfruttate e nelle azioni che hanno portato ai gol avversari.':'Il risultato lascia entrambe le squadre a interrogarsi sulle occasioni che avrebbero potuto fare la differenza.';
      if(number(s.total_shots)!==null&&number(s.shots_on_target)!==null)reading+=` ${f[side]} ha concluso ${s.total_shots} volte, ${s.shots_on_target} nello specchio: il rapporto fra questi due numeri aiuta a leggere la precisione, senza attribuire automaticamente lo stesso valore a ogni tiro.`;
      if(t?.formation)reading+=` La scelta iniziale era il ${t.formation}.`;
      blocks.push({speaker:side+'_reporter',text:reading});
      const q=landmark?`Mister, torniamo al ${landmark.minute}′, al gol di ${landmark.player_name}. ${conceded.length?'Come giudichi la gestione della partita dopo quella rete subita?':'Quanto ha cambiato la partita quella rete e che cosa serviva fare subito dopo?'}`:'Mister, non avete subito gol ma non siete riusciti a segnare. Da quale delle due fasi parti per valutare questa partita?';
      const answer=conceded.length?(gf>ga?'Mi piace che la squadra abbia trovato il modo di chiudere avanti, ma quel gol ci ricorda che dobbiamo migliorare. Non voglio che la vittoria cancelli le situazioni che abbiamo concesso.':gf<ga?'Dobbiamo rivedere come abbiamo difeso quell’azione e come abbiamo reagito. Il risultato ci chiede un’analisi sincera: non possiamo limitarci a sperare che l’occasione successiva cambi tutto.':'Una rete subita va analizzata anche quando poi il risultato resta in equilibrio. Voglio capire cosa potevamo fare meglio nell’azione e come rendere più efficace la nostra risposta.'):(gf>0?'Il gol ci ha dato qualcosa da difendere, ma non volevo che diventasse un motivo per smettere di giocare. La gestione passa anche dalla capacità di continuare a proporci.':'La solidità è una base da conservare. Davanti, però, dobbiamo trovare più qualità nelle scelte: il fatto di non aver subito non risolve ciò che ci è mancato per segnare.');
      blocks.push({speaker:side+'_question',text:q},{speaker:side+'_manager',text:answer});
      const q2=t?.formation?`Avevi scelto il ${t.formation}${t.mentality?', con mentalità '+t.mentality.toLowerCase():''}. Alla luce di ciò che avete prodotto, quanto sei soddisfatto dell’equilibrio fra attacco e difesa?`:'Quanto sei soddisfatto dell’equilibrio fra le occasioni costruite e quelle concesse?';
      const a2=gf>ga?'La scelta va giudicata attraverso il lavoro della squadra. Abbiamo trovato soluzioni utili per vincere, ma dobbiamo rivedere anche i momenti in cui non siamo riusciti a controllare il gioco. Voglio continuità, non soltanto un risultato favorevole.':'Il modulo da solo non dà una risposta. Dobbiamo guardare le distanze, il sostegno a chi ha il pallone e la protezione quando lo perdiamo. Se il risultato non è quello che cercavamo, anche le mie scelte vanno analizzate insieme alla prestazione.';
      blocks.push({speaker:side+'_question',text:q2},{speaker:side+'_manager',text:a2});
      const scorer=own[0];
      const q3=scorer?`${scorer.player_name} ha trovato la rete. Che cosa vuoi conservare del contributo dei giocatori arrivati alla conclusione?`:number(s.shots_on_target)!==null?`Avete chiuso con ${s.shots_on_target} conclusioni nello specchio. Dove cerchi il miglioramento per rendere più efficace l’ultima parte dell’azione?`:'Che cosa chiedi alla squadra di migliorare nella scelta dell’ultima giocata?';
      const a3=scorer?'Voglio che quel contributo abbia continuità. Il gol è importante, ma dobbiamo lavorare anche per creare altre situazioni favorevoli e coinvolgere più giocatori. Non possiamo chiedere a una sola conclusione di spiegare tutta la nostra prestazione.':'Nelle scelte e nel sostegno a chi deve concludere. Non basta arrivare vicino alla porta: dobbiamo capire quando tirare, quando cercare un compagno e come occupare meglio gli spazi. È un lavoro di squadra, non una responsabilità da lasciare soltanto agli attaccanti.';
      blocks.push({speaker:side+'_question',text:q3},{speaker:side+'_manager',text:a3});
    }
    blocks.push({speaker:'studio',text:'Torniamo in studio. Abbiamo ascoltato entrambi gli allenatori: leggiamo ora gli episodi e le prestazioni senza fermarci al punteggio.'});
    blocks.push({speaker:'context',text:first&&last&&first!==last?`Il percorso del risultato comincia con ${first.player_name} al ${first.minute}′ e arriva all’ultima rete di ${last.player_name} al ${last.minute}′. È questa successione che va tenuta insieme al punteggio finale: una partita cambia anche nel tempo che le squadre hanno a disposizione per reagire.${penaltyText}`:`${opening} Il risultato va letto dentro questa partita, senza trasformarlo da solo in un giudizio definitivo sul percorso delle due squadre.${penaltyText}`});
    const hs=m.stats.home||{},as=m.stats.away||{};
    blocks.push({speaker:'defence',text:`${a===0?f.home+' mantiene la porta inviolata.':f.home+' subisce '+a+' gol.'} ${h===0?f.away+' chiude senza concedere reti.':f.away+' incassa '+h+' gol.'} ${number(hs.shots_on_target)!==null&&number(as.shots_on_target)!==null?`Le conclusioni nello specchio sono ${hs.shots_on_target} a ${as.shots_on_target}: aiutano a misurare quanto sono stati impegnati i portieri, ma per giudicare ogni situazione va considerata anche l’azione che l’ha prodotta.`:'L’analisi difensiva deve cominciare dalle azioni concesse e dal lavoro necessario per impedire all’avversario di tornare a concludere.'}`});
    blocks.push({speaker:'attack',text:mvp?`${mvp.player_name} è il migliore in campo indicato dal report${number(mvp.rating)!==null?', con voto '+mvp.rating:''}. ${Number(mvp.goals)>0?'Il suo contributo comprende '+mvp.goals+' gol.':'È un riconoscimento che ci invita a guardare anche oltre il numero dei gol.'} ${Number(mvp.assists)>0?'Ci sono anche '+mvp.assists+' assist: il pallone che mette un compagno in condizione di segnare è parte della stessa azione decisiva.':'Per valutare l’attacco bisogna tenere insieme chi conclude e il lavoro di chi rende possibile la conclusione.'}`:'La valutazione offensiva deve distinguere il volume dei tentativi dalla loro efficacia. I gol raccontano le azioni riuscite; quelle non concluse bene indicano dove cercare maggiore precisione e migliori scelte.'});
    blocks.push({speaker:'studio',text:`Si chiude così ${f.home}–${f.away}: ${h}–${a}.${penaltyText} Le voci dai due campi ci hanno aiutato a entrare nella partita, dalle scelte iniziali agli episodi che hanno deciso il risultato.`});
    return blocks;
  }
  function commentary(m) {
    if(!m.report)return [];
    return (approvedStory(m)?.blocks || automaticStory(m)).map(b=>voiced(m,b));
  }

  if (typeof module !== 'undefined' && module.exports) { module.exports = { buildMatch, commentary, validRow, attachEditorial, approvedStory, automaticStory }; return; }
  const panel = document.getElementById('panel-final-whistle'), dateInput = document.getElementById('date');
  if (!panel || !dateInput) return;
  const root = document.createElement('section'); root.className = 'fw-edition'; panel.append(root);
  const el = (tag, text, cls) => { const n = document.createElement(tag); if (text != null) n.textContent = text; if (cls) n.className = cls; return n; };
  let generation = 0, controller, selected = 0, state = null, portraits = {}, busy = false, lastSignature = '';
  const oldEmpty = panel.querySelector('.programme-empty');
  function visibility() {
    const archived = dateInput.value === '2026-10-20'; root.hidden = archived;
    if (oldEmpty) oldEmpty.hidden = true;
  }
  function photo(src, name, cls) { const img = el('img', null, cls); img.src = src; img.alt = name; img.loading = 'lazy'; img.addEventListener('error', () => { img.hidden = true; }); return img; }
  function speech(name, role, text) {
    const box = el('article', null, 'fw-speech'), head = el('header', null, 'fw-person');
    const p = state?.coffee.reporter_portraits?.[name]?.image || portraits[name]?.url;
    if (p) head.append(photo(p, name));
    head.append(el('strong', name), el('small', role)); box.append(head, el('p', text)); return box;
  }
  function choose(index) {
    selected = index;
    root.querySelectorAll('[role=tab]').forEach((b,i) => { b.setAttribute('aria-selected', String(i === index)); b.tabIndex = i === index ? 0 : -1; });
    root.querySelectorAll('[role=tabpanel]').forEach((p,i) => p.hidden = i !== index);
  }
  function render() {
    root.replaceChildren(); if (!state) return;
    const {coffee, matches, errors, checked} = state, completed = matches.filter(m => m.row).length, reports = matches.filter(m => m.report).length;
    const morning=coffee.title || 'Le partite di Coffee Time';
    const cupMorning=morning==='Il caffè della coppa: otto squadre, quattro posti';
    const allPlayed=completed===matches.length;
    const headline=cupMorning ? (allPlayed?'La notte della coppa: otto squadre, quattro semifinaliste':'La notte della coppa: quattro posti da conquistare') : morning.replace(/^Il caffè/i,'La serata')+(completed?' · Il verdetto del campo':' · In attesa del fischio d’inizio');
    const title=el('header',null,'fw-title');title.append(el('p',coffee.label || coffee.date+' · GW001','eyebrow'),el('h2',headline),el('p',allPlayed ? `${matches.length} partite giocate · Le voci dei protagonisti` : completed ? `${completed} partite concluse · La serata continua` : `${matches.length} partite · Le voci dai campi`));root.append(title);
    const archive=document.querySelector('.edition-archive nav');
    if(archive && coffee.editions){archive.replaceChildren();for(const date of coffee.editions){const a=el('a',date,'archive-link');a.href=date==='2026-10-20'?'/roadtohistory/alltoplayfor/final-whistle/2026-10-20/':'/roadtohistory/alltoplayfor/final-whistle/?date='+date;archive.append(a);}}
    if (errors) root.append(el('p', 'Alcune fonti non sono raggiungibili. I dati non verificabili sono segnalati nei singoli incontri; riproveremo al prossimo aggiornamento.', 'fw-warning'));
    const welcome=cupMorning && allPlayed ? 'Buonasera e benvenuti a Final Whistle. Si sono giocati i quattro quarti di finale di coppa. Questa mattina erano otto squadre per quattro posti: ora la serata ha dato i suoi verdetti. Andiamo dai protagonisti.' : allPlayed ? `Buonasera e benvenuti a Final Whistle. Si sono giocate le ${matches.length} partite presentate questa mattina a Coffee Time. Ripercorriamo la serata con le voci dei protagonisti.` : completed ? `Buonasera e benvenuti a Final Whistle. Si sono concluse ${completed} delle ${matches.length} partite di questa serata. Cominciamo dai campi che hanno già dato il loro verdetto.` : 'Benvenuti a Final Whistle. Ci ritroveremo al termine delle partite presentate questa mattina a Coffee Time, per ascoltare i protagonisti e raccontare la serata.';
    root.append(speech(...cast[0],welcome));
    const nav = el('nav', null, 'fw-tabs'); nav.setAttribute('role','tablist'); nav.setAttribute('aria-label','Divisioni Final Whistle');
    coffee.divisions.forEach((d,i) => { const b = el('button', d.name.replace(/^Div\s*/, 'Divisione ')); b.type = 'button'; b.id = 'fw-tab-'+i; b.setAttribute('role','tab'); b.setAttribute('aria-controls','fw-division-'+i); b.addEventListener('click',()=>choose(i)); nav.append(b); });
    nav.addEventListener('keydown', e => { let n=selected; if(e.key==='ArrowRight') n=(n+1)%coffee.divisions.length; else if(e.key==='ArrowLeft') n=(n+coffee.divisions.length-1)%coffee.divisions.length; else if(e.key==='Home') n=0; else if(e.key==='End') n=coffee.divisions.length-1; else return; e.preventDefault(); choose(n); nav.children[n].focus(); }); root.append(nav);
    for (const [i,d] of coffee.divisions.entries()) {
      const section=el('section',null,'fw-division'); section.id='fw-division-'+i; section.setAttribute('role','tabpanel'); section.setAttribute('aria-labelledby','fw-tab-'+i); section.append(el('h2',d.name));
      for (const f of d.fixtures) {
        const m=matches.find(m=>String(m.fixture.id)===String(f.id)), card=el('article',null,'fw-match'); card.id='fw-match-'+f.id; card.dataset.fixture=f.id;
        const teams=el('div',null,'fw-scoreboard');
        for(const side of ['home','away']) { const t=el('div',null,'fw-team'); t.append(photo(f[side+'_logo'],''),el('strong',f[side]),el('small',f[side+'_manager'])); teams.append(t); if(side==='home') teams.append(el('strong',m.row ? `${m.row.home_score}–${m.row.away_score}` : '–','fw-score')); }
        const editorial=approvedStory(m);
        if(editorial)card.append(el('h3',editorial.title,'fw-story-title'));
        card.append(teams,el('p', m.error ? 'Verifica incompleta: fonte temporaneamente non disponibile.' : m.report ? 'Fischio finale · Il dopopartita' : m.row ? 'Fischio finale · In attesa dei protagonisti' : 'Calcio d’inizio · Ore '+(f.time||'da confermare'),'fw-status'));
        const penalties=editorial?.penalties || (number(m.row?.penalty_home_score)!==null && number(m.row?.penalty_away_score)!==null ? [m.row.penalty_home_score,m.row.penalty_away_score] : null);
        if(penalties)card.append(el('p',`Rigori: ${penalties[0]}–${penalties[1]}`,'fw-penalties'));
        if(m.conflict) card.append(el('p','Results e Match Report riportano punteggi diversi: viene mostrato il Match Report, fonte prioritaria.','fw-warning'));
        if(m.report) {
          const details=el('details',null,'fw-report-details');details.append(el('summary','Tabellino, statistiche e migliore in campo'));card.append(details);
          const goals=el('div',null,'fw-goals'); for(const g of [...m.goals].sort((a,b)=>Number(a.minute)-Number(b.minute))) goals.append(el('p',`${g.minute ?? '–'}′ · ${g.player_name}${g.own_goal ? ' (autorete)' : ''} · ${f[g.team_side] || ''}`));
          if(m.goals.length) details.append(goals);
          const table=el('table'), cap=el('caption','I numeri della partita'); table.append(cap); const body=el('tbody');
          for(const [key,label] of [['possession','Possesso %'],['total_shots','Tiri'],['shots_on_target','Nello specchio'],['corners','Corner'],['red_cards','Espulsioni']]) {const tr=el('tr'),th=el('th',label);th.scope='row';tr.append(el('td',m.stats.home?.[key]??'–'),th,el('td',m.stats.away?.[key]??'–'));body.append(tr);} table.append(body); details.append(table);
          const mvp=m.players.find(p=>Number(p.man_of_match)===1); if(mvp) {const award=el('aside',null,'fw-mvp'); if(/^\d+$/.test(String(mvp.sm_player_id))) award.append(photo('https://cdn.soccerwiki.org/images/player/'+mvp.sm_player_id+'.png',mvp.player_name)); award.append(el('small','MIGLIORE IN CAMPO'),el('strong',mvp.player_name),el('span','Voto '+(mvp.rating??'non disponibile'))); details.append(award);}
        }
        for(const line of commentary(m)) {const block=speech(line.name,line.role,line.text);block.classList.add('fw-'+line.kind);card.append(block);}
        if(coffee.mode!=='schedule-preview'&&!m.row) card.append(el('p',(f.reporters||[]).map(r=>`${r.name} · ${r.club} · ${r.label}`).join(' | '),'fw-correspondents'));
        const links=el('div',null,'fw-links'); const sources=[['Coffee Time',`/roadtohistory/alltoplayfor/coffee-time/${coffee.date}/`],['Results',`/roadtohistory/clubs/matches.php?world=GW001&sm_club=${f.home_table.id}`]]; if(m.report) sources.push(['Match Report',`/roadtohistory/competitions/match-report.php?world=GW001&fixture=${f.id}`]); for(const [label,href] of sources){const a=el('a',label);a.href=href;links.append(a);}card.append(links);section.append(card);
      }
      root.append(section);
    }
    choose(Math.min(selected,coffee.divisions.length-1));
    window.finalWhistleDesign?.(root,state);
  }
  async function json(url, signal) {
    const response=await fetch(url+(url.includes('?')?'&':'?')+'_fw='+Date.now(),{cache:'no-store',signal});
    if(response.status===404) return null;
    if(!response.ok) throw Error('Fonte non disponibile'); const data=await response.json(); if(data?.ok===false) throw Error('Fonte non disponibile'); return data;
  }
  async function pool(items, fn) {const out=new Array(items.length);let cursor=0;await Promise.all(Array.from({length:Math.min(4,items.length)},async()=>{while(cursor<items.length){const i=cursor++;out[i]=await fn(items[i]);}}));return out;}
  const currentDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const followsToday=()=>!document.body.dataset.edition && !new URL(location.href).searchParams.has('date');
  async function load(reset=true) {
    if(followsToday() && dateInput.value!==currentDate()){dateInput.value=currentDate();reset=true;}

    visibility(); if(root.hidden || panel.hidden || (!reset && busy)) return;
    const date=dateInput.value; if(!/^\d{4}-\d{2}-\d{2}$/.test(date)) return;
    controller?.abort(); controller=new AbortController();const signal=controller.signal,token=++generation;busy=true;
    if(reset){state=null;lastSignature='';selected=0;root.replaceChildren(el('p','Caricamento della giornata di Final Whistle…'));}
    const timeout=setTimeout(()=>controller && token===generation && controller.abort(),60000);
    try {
      const source=await json(`coffee-source.php?date=${date}`,signal);
      const coffee=source?.edition;
      if(!coffee){root.replaceChildren(el('p','Nessuna edizione di Coffee Time disponibile per questa data. Final Whistle seguirà le partite quando sarà pubblicata.'));return;}
      if(coffee.date!==date || coffee.world!=='GW001' || !Array.isArray(coffee.divisions) || !coffee.divisions.length) throw Error('Edizione Coffee Time non valida');
      const seen=new Set();for(const d of coffee.divisions)for(const f of d.fixtures){if(!/^\d+$/.test(String(f.id))||!f.home_table?.id||!f.away_table?.id||seen.has(String(f.id)))throw Error('Partite non valide');seen.add(String(f.id));}
      const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
      if(coffee.mode==='schedule-preview' && date>today){
        state={coffee,matches:coffee.divisions.flatMap(d=>d.fixtures).map(f=>buildMatch(f,date,null,null)),errors:false,checked:new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit'}).format(new Date())};
        render();return;
      }
      portraits=await json('portraits.json',signal)||{};
      const matches=await pool(coffee.divisions.flatMap(d=>d.fixtures),async f=>{
        const r=await Promise.allSettled([json(`/roadtohistory/clubs/matches.php?world=GW001&sm_club=${f.home_table.id}`,signal),json(`/roadtohistory/competitions/match-report.php?world=GW001&fixture=${f.id}`,signal)]);
        const m=buildMatch(f,date,r[0].status==='fulfilled'?r[0].value:null,r[1].status==='fulfilled'?r[1].value:null);m.error=r.some(x=>x.status==='rejected');await attachEditorial(m);return m;
      });
      if(token!==generation || date!==dateInput.value) return;
      if(signal.aborted) throw Error('Verifica scaduta');
      if(matches.some(m=>m.row))coffee.mode='postmatch';
      state={coffee,matches,errors:matches.some(m=>m.error),checked:new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit'}).format(new Date())};
      const signature=JSON.stringify([coffee,matches]);
      if(signature!==lastSignature){lastSignature=signature;render();}
      else {const p=root.querySelector('.fw-update p');if(p)p.textContent=`Dati verificati alle ${state.checked}.`;}
    } catch(error) {
      if(token!==generation) return;
      if(state){const message=root.querySelector('.fw-update p');if(message)message.textContent='Aggiornamento non riuscito: restano visibili i dati dell’ultima verifica.';}
      else root.replaceChildren(el('p','Impossibile verificare i dati Nexus. Ricarica la pagina per riprovare.','fw-warning'));
    } finally {clearTimeout(timeout);if(token===generation)busy=false;}
  }
  document.addEventListener('programme-date-change',()=>{controller?.abort();++generation;busy=false;visibility();load(true);});
  document.addEventListener('postmatch-ready',visibility);
  new MutationObserver(()=>{if(!panel.hidden)load(true);}).observe(panel,{attributes:true,attributeFilter:['hidden']});

  
  const url=new URL(location.href);
  if(/^\d{4}-\d{2}-\d{2}$/.test(url.searchParams.get('date')||''))dateInput.value=url.searchParams.get('date');
  if(followsToday()) {dateInput.value=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());load(true);}
  else load(true);
})();
